UPDATE public.conferences_service_items SET "name" = 'Ekrany LED do konferencji i gal', "description" = 'Ekrany LED, prezentacje i realizacja obrazu podczas konferencji, gal i eventów.', "long_description" = 'Własne ekrany LED MAVINCI do konferencji, gal i wydarzeń firmowych. Przygotowujemy obraz dla prezentacji, materiałów wideo i oprawy sceny, a format ekranu dobieramy do przestrzeni oraz scenariusza. Zapewniamy przygotowanie, montaż i obsługę multimediów. Pracujemy z Olsztyna na Warmii i Mazurach oraz przy realizacjach w innych regionach Polski. Szczegółową konfigurację ekranu i wymagania techniczne potwierdzamy w ofercie.', "seo_title" = 'Ekrany LED na konferencje i gale Olsztyn | MAVINCI', "seo_description" = 'Ekrany LED, prezentacje i multimedia na konferencje, gale oraz eventy. Własne zaplecze MAVINCI w Olsztynie. Realizacje na Warmii i Mazurach.', "seo_keywords" = 'ekrany LED Olsztyn, ekrany LED konferencje, multimedia Warmia Mazury', "features" = ARRAY['Własne ekrany LED','Format dobierany do przestrzeni i programu','Obsługa prezentacji i materiałów wideo','Montaż i realizacja multimediów']::text[], "technical_specs" = '{"Zastosowanie": "Konferencje, gale i wydarzenia firmowe", "Konfiguracja": "Format i parametry potwierdzane w indywidualnej ofercie"}'::jsonb WHERE id = 'b1dc8e24-a4c2-4d74-bf39-7ac36a83e550' AND "name" IS NOT DISTINCT FROM 'Ekrany LED do konferencji i gall' AND "description" IS NOT DISTINCT FROM 'Duże formaty LED do prezentacji i eventów premium' AND "long_description" IS NOT DISTINCT FROM 'Ściany LED premium do konferencji i gal. Duże formaty ekranów LED tworzące efektowne tło dla prezentacji, koncertów i eventów korporacyjnych. Możliwość realizacji ścian od 3x2m do 10x6m.' AND "seo_title" IS NOT DISTINCT FROM 'LED do Konferencji i Gal - Wynajem | MAVINCI' AND "seo_description" IS NOT DISTINCT FROM 'Duże ściany LED premium do eventów. Formaty od 3x2m do 10x6m, pitch 2.9-4mm, wsparcie 4K/8K. Warszawa, Gdańsk.' AND "seo_keywords" IS NOT DISTINCT FROM 'ściana led konferencja, ściana led event, duży ekran led, tło led scena, led wall wynajem' AND "features" IS NOT DISTINCT FROM ARRAY['Formaty od 3x2m do 10x6m','Pitch 2.6mm','Brak widocznych łączeń','Profesjonalna kalibracja kolorów']::text[] AND "technical_specs" IS NOT DISTINCT FROM '{"depth": "80mm", "pitch": "2.9mm - 4mm", "refresh": "3840Hz", "brightness": "1500 nits", "Rozmiar Kabinetu": "500x500mm"}'::jsonb;

