UPDATE public.conferences_service_items SET "name" = 'Nagłośnienie Meyer Sound LINA', "description" = 'Własny system line-array Meyer Sound LINA z obsługą realizatorską.', "long_description" = 'MAVINCI dysponuje własnym systemem nagłośnieniowym Meyer Sound LINA. Zapewniamy dobór konfiguracji, przygotowanie i realizację dźwięku podczas konferencji, koncertów, gal i wydarzeń firmowych. Wielkość systemu dobieramy do akustyki obiektu, układu publiczności i wymagań programu. Nasza baza znajduje się przy ul. Towarowej 20B w Olsztynie. Obsługujemy Warmię i Mazury oraz wydarzenia w innych regionach Polski.', "seo_title" = 'Nagłośnienie Meyer Sound LINA Olsztyn | MAVINCI', "seo_description" = 'Własny system Meyer Sound LINA i realizacja dźwięku na konferencje, koncerty i gale. MAVINCI Olsztyn — obsługa Warmii i Mazur oraz wydarzeń w Polsce.', "seo_keywords" = 'Meyer Sound LINA, nagłośnienie Olsztyn, technika eventowa Warmia Mazury', "features" = ARRAY['Własny system Meyer Sound LINA','Dobór konfiguracji do miejsca i programu','Montaż i realizacja dźwięku','Obsługa konferencji, koncertów i gal']::text[], "technical_specs" = '{"Producent": "Meyer Sound", "Model": "LINA", "Typ": "Line array", "Konfiguracja": "Dobierana do projektu"}'::jsonb WHERE id = '8b02f14c-1883-4bb0-b88c-bf8fae04c91b' AND "name" IS NOT DISTINCT FROM 'Systemy line-array Meyer Sound - LINA' AND "description" IS NOT DISTINCT FROM 'Premium nagłośnienie dla dużych konferencji i eventów' AND "long_description" IS NOT DISTINCT FROM 'System nagłośnieniowy Meyer Sound - LINAy - topowy line-array dla dużych konferencji, koncertów i eventów premium. Krystalicznie czysty dźwięk, ogromna moc i precyzyjne pokrycie akustyczne. Idealny dla sal od 500 do 5000 osób.' AND "seo_title" IS NOT DISTINCT FROM 'Nagłośnienie Meyer Sound - LINA - Wynajem | MAVINCI' AND "seo_description" IS NOT DISTINCT FROM 'Premium nagłośnienie Meyer Sound - LINA line-array do wynajęcia. 130dB SPL, pokrycie do 5000 osób. Warszawa, Gdańsk, Bydgoszcz.' AND "seo_keywords" IS NOT DISTINCT FROM 'coda audio, line array wynajem, nagłośnienie premium, nagłośnienie konferencja, system line array' AND "features" IS NOT DISTINCT FROM ARRAY['Meyer Sound - LINA','130dB SPL max','Pokrycie do 5000 osób','Precyzyjne targetowanie akustyczne']::text[] AND "technical_specs" IS NOT DISTINCT FROM '{"type": "Line Array", "weight": "29kg", "spl_max": "130dB", "coverage": "90° x 10°", "amplifier": "Class D 2000W", "frequency": "50Hz - 18kHz"}'::jsonb;

